        P.push(px - dz * ww * sgn, y, pz + dx * ww * sgn); N.push(nn.x, nn.y, nn.z);
        const c = (isDry ? dry : base).clone().lerp(isDry ? dry : tip, t * t), sh = 0.62 + 0.38 * t;
